/* ============================================================
 * 一字千年 · 甲骨文字形 CNN 分类器（离线训练，纯 JS 推理）
 * ------------------------------------------------------------
 * 训练数据：项目字库 119 字 × 5 书体 + 程序化扰动 + HUST-OBC 真实拓片
 * 输入：Vision.extract() 的 normRaw(96×96 0/1) 经 2×2 平均池化 → 48×48
 * 输出：119 类 softmax（经温度校准，可直接当置信度使用）
 * 权重：float32 无损，base64 内嵌；无任何外部依赖，可完全离线运行
 * ============================================================ */
const OBICNN = (() => {
  const META = {"ncls": 119, "T": 0.94, "keys": ["c1.weight", "c1.bias", "c2.weight", "c2.bias", "c3.weight", "c3.bias", "f1.weight", "f1.bias", "f2.weight", "f2.bias"], "shapes": [[8, 1, 3, 3], [8], [16, 8, 3, 3], [16], [24, 16, 3, 3], [24], [128, 864], [128], [119, 128], [119]], "chars": ["日", "月", "山", "水", "火", "人", "木", "田", "鱼", "鸟", "鹿", "马", "牛", "羊", "犬", "目", "女", "子", "门", "雨", "云", "弓", "鼎", "心", "一", "二", "三", "天", "上", "下", "中", "东", "南", "北", "夕", "白", "光", "明", "春", "秋", "年", "岁", "千", "百", "左", "右", "旦", "晶", "冬", "夏", "晨", "大", "口", "耳", "王", "高", "见", "舌", "面", "首", "立", "走", "老", "好", "美", "力", "友", "问", "儿", "父", "母", "男", "生", "朋", "土", "石", "川", "井", "谷", "河", "泉", "玉", "风", "雷", "雪", "气", "丘", "潭", "彩", "禾", "米", "竹", "林", "森", "豆", "工", "衣", "食", "家", "酒", "刀", "网", "车", "舟", "宫", "壶", "鼓", "典", "虫", "凤", "兔", "鸡", "虎", "鼠", "龟", "贝", "龙", "雀", "燕"], "top1": 0.7976, "top3": 0.8824, "ece": 0.028};
  const B64 = "";
  let W = null;

  function decode() {
    const s = atob(B64);
    const buf = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) buf[i] = s.charCodeAt(i);
    const dv = new DataView(buf.buffer);
    const out = {}, names = META.keys, shapes = META.shapes;
    let off = 0;
    for (let k = 0; k < names.length; k++) {
      const n = shapes[k].reduce((a, b) => a * b, 1);
      const a = new Float32Array(n);
      for (let i = 0; i < n; i++) { a[i] = dv.getFloat32(off, true); off += 4; }
      out[names[k]] = { a, s: shapes[k] };
    }
    return out;
  }

  /* 3×3 conv, pad=1, stride=1；in/out 均为 [C][H][W] 展平 */
  function conv(input, CI, HI, WI, w, b, CO) {
    const o = new Float32Array(CO * HI * WI);
    for (let oc = 0; oc < CO; oc++) {
      const wo = oc * CI * 9, bo = b[oc];
      for (let oy = 0; oy < HI; oy++) for (let ox = 0; ox < WI; ox++) {
        let acc = bo;
        for (let ic = 0; ic < CI; ic++) {
          const xi = ic * HI * WI, wi = wo + ic * 9;
          for (let ky = -1; ky <= 1; ky++) {
            const yy = oy + ky;
            if (yy < 0 || yy >= HI) continue;
            for (let kx = -1; kx <= 1; kx++) {
              const xx = ox + kx;
              if (xx < 0 || xx >= WI) continue;
              acc += input[xi + yy * WI + xx] * w[wi + (ky + 1) * 3 + (kx + 1)];
            }
          }
        }
        o[oc * HI * WI + oy * WI + ox] = acc > 0 ? acc : 0;   // ReLU
      }
    }
    return o;
  }

  function maxpool2(input, C, H, W) {
    const H2 = H >> 1, W2 = W >> 1;
    const o = new Float32Array(C * H2 * W2);
    for (let c = 0; c < C; c++) for (let oy = 0; oy < H2; oy++) for (let ox = 0; ox < W2; ox++) {
      const i = c * H * W + 2 * oy * W + 2 * ox;
      let m = input[i];
      const v = [input[i + 1], input[i + W], input[i + W + 1]];
      for (let k = 0; k < 3; k++) if (v[k] > m) m = v[k];
      o[c * H2 * W2 + oy * W2 + ox] = m;
    }
    return o;
  }

  function linear(x, w, b, IN, OUT, relu) {
    const o = new Float32Array(OUT);
    for (let j = 0; j < OUT; j++) {
      let acc = b[j];
      const wo = j * IN;
      for (let i = 0; i < IN; i++) acc += x[i] * w[wo + i];
      o[j] = (relu && acc < 0) ? 0 : acc;
    }
    return o;
  }

  /** normRaw: Uint8Array(96*96), 0/1。返回 {top:[{char,conf}], ok} */
  function predict(normRaw, topN) {
    if (!W) W = decode();
    const N = topN || 5;
    // 96→48 2×2 平均池化
    const inp = new Float32Array(48 * 48);
    for (let y = 0; y < 48; y++) for (let x = 0; x < 48; x++) {
      const i = 2 * y * 96 + 2 * x;
      inp[y * 48 + x] = (normRaw[i] + normRaw[i + 1] +
                         normRaw[i + 96] + normRaw[i + 97]) / 4;
    }
    let a = conv(inp, 1, 48, 48, W["c1.weight"].a, W["c1.bias"].a, 8);
    a = maxpool2(a, 8, 48, 48);                     // 8×24×24
    a = conv(a, 8, 24, 24, W["c2.weight"].a, W["c2.bias"].a, 16);
    a = maxpool2(a, 16, 24, 24);                    // 16×12×12
    a = conv(a, 16, 12, 12, W["c3.weight"].a, W["c3.bias"].a, 24);
    a = maxpool2(a, 24, 12, 12);                    // 24×6×6 = 864
    a = linear(a, W["f1.weight"].a, W["f1.bias"].a, 864, 128, true);
    const logits = linear(a, W["f2.weight"].a, W["f2.bias"].a, 128, META.ncls, false);
    // softmax(T)，数值稳定
    let mx = -Infinity;
    for (let i = 0; i < META.ncls; i++) if (logits[i] / META.T > mx) mx = logits[i] / META.T;
    let sum = 0;
    const p = new Float32Array(META.ncls);
    for (let i = 0; i < META.ncls; i++) { p[i] = Math.exp(logits[i] / META.T - mx); sum += p[i]; }
    for (let i = 0; i < META.ncls; i++) p[i] /= sum;
    const order = Array.from({ length: META.ncls }, (_, i) => i)
      .sort((x, y) => p[y] - p[x]).slice(0, N);
    return {
      ok: true,
      top: order.map(i => ({ idx: i, char: META.chars[i], conf: +p[i].toFixed(4) })),
      entropy: -Array.from(p).reduce((s, v) => s + (v > 0 ? v * Math.log(v) : 0), 0)
    };
  }

  return { predict, meta: META };
})();
